const OLLAMA = 'http://ollama:11434';
const QDRANT = 'http://qdrant:6333';
const COLECCION = 'ishop_rag_v2';
const MODELO = 'nomic-embed-text:latest';
const TAMANO_FRAGMENTO = 900;
const LOTE = 16;

const entrada = $input.first().json;
const formulario = $('Formulario de carga').first().json;
const tema = String(formulario['Tema del documento'] || 'Documento sin título').trim();
const archivo = formulario.Archivo?.[0]?.filename || formulario.Archivo?.filename || 'documento';

const texto = String(entrada.text || entrada.data || '').replace(/\r/g, '').trim();
if (!texto) {
  return [{ json: { ok: false, mensaje: 'No se pudo leer texto del archivo. Si es un PDF escaneado como imagen, no contiene texto extraíble.' } }];
}

// Se corta por párrafos para no partir una frase a la mitad.
const fragmentos = [];
let actual = '';
for (const parrafo of texto.split(/\n{2,}/)) {
  const limpio = parrafo.trim();
  if (!limpio) continue;
  if ((actual + '\n\n' + limpio).length > TAMANO_FRAGMENTO && actual) {
    fragmentos.push(actual.trim());
    actual = limpio;
  } else {
    actual = actual ? `${actual}\n\n${limpio}` : limpio;
  }
}
if (actual.trim()) fragmentos.push(actual.trim());

if (!fragmentos.length) {
  return [{ json: { ok: false, mensaje: 'El archivo no tiene contenido que indexar.' } }];
}

// Los identificadores arrancan en mil millones para no chocar con los
// correlativos que usa index_knowledge.py para el catálogo.
let identificador = 1000000000 + Math.floor(Date.now() / 1000) * 100;
let guardados = 0;

for (let inicio = 0; inicio < fragmentos.length; inicio += LOTE) {
  const lote = fragmentos.slice(inicio, inicio + LOTE);
  const textos = lote.map((fragmento) => `${tema}\n${fragmento}`);

  const respuesta = await this.helpers.httpRequest({
    method: 'POST',
    url: `${OLLAMA}/api/embed`,
    body: { model: MODELO, input: textos, keep_alive: -1 },
    json: true,
    timeout: 180000,
  });

  const vectores = respuesta.embeddings || [];
  if (vectores.length !== lote.length) {
    throw new Error('Ollama no devolvió un vector por fragmento');
  }

  const puntos = lote.map((fragmento, posicion) => ({
    id: identificador++,
    vector: vectores[posicion],
    payload: {
      doc_kind: 'information',
      origin: 'carga_manual',
      category: 'documento_cargado',
      title: tema,
      source: archivo,
      content: fragmento,
    },
  }));

  await this.helpers.httpRequest({
    method: 'PUT',
    url: `${QDRANT}/collections/${COLECCION}/points?wait=true`,
    body: { points: puntos },
    json: true,
    timeout: 180000,
  });

  guardados += puntos.length;
}

return [{
  json: {
    ok: true,
    tema,
    archivo,
    fragmentos: guardados,
    mensaje: `Se guardaron ${guardados} fragmentos de "${tema}". El asistente ya puede responder con este contenido.`,
  },
}];
